from concurrent.futures import ThreadPoolExecutor, as_completed
BIN='/workspace/artifacts/target/exiv2'
SIG=b'\x89PNG\r\n\x1a\n'
def chunk(t,d):
    return struct.pack('>I',len(d))+t+d+struct.pack('>I',zlib.crc32(t+d)&0xffffffff)
def build_png(rng):
    ihdr=struct.pack('>IIBBBBB',1,1,8,2,0,0,0)
    chunks=[chunk(b'IHDR',ihdr)]
    # add random metadata chunks
    for _ in range(rng.randint(1,15)):
        typ=rng.choice([b'eXIf',b'iTXt',b'tEXt',b'zTXt',b'tIME',b'IDAT',b'IEND',b'pHYs',b'sRGB'])
        if typ==b'IEND':
            data=b''
        elif typ==b'IDAT':
            data=os.urandom(rng.randint(0,50))
        elif typ==b'eXIf':
            # little tiff body
            data=os.urandom(rng.randint(0,200))
        elif typ==b'tIME':
            data=struct.pack('>HBBBBB',rng.randint(0,9999),1,1,0,0,0)
        elif typ==b'iTXt':
            keyword=os.urandom(rng.randint(0,30))
            data=keyword+b'\0\x00\x00'+os.urandom(rng.randint(0,200))
        elif typ==b'tEXt':
            data=b'key\0'+os.urandom(rng.randint(0,100))
        elif typ==b'zTXt':
            data=b'key\0\x00'+os.urandom(rng.randint(0,100))
        else:
            data=os.urandom(rng.randint(0,30))
        # mutate length sometimes
        if rng.random()<0.3:
            fake_len=rng.choice([0,1,2,4,8,len(data),len(data)+1,len(data)-1,0x7fffffff,0xffffffff])
            chunks.append(struct.pack('>I',fake_len)+typ+data)
        else:
            chunks.append(chunk(typ,data))
    # ensure IEND at end if none
    if not any(b.startswith(chunk(b'IEND',b'')[:4]) for b in []):
        chunks.append(chunk(b'IEND',b''))
    return SIG+b''.join(chunks)

def run_one(data):
    fd,p=tempfile.mkstemp(suffix='.png',dir='/tmp'); os.write(fd,data); os.close(fd)
    try:
        r=subprocess.run([BIN,'-pR',p],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=1.0)
        return r.returncode, data
    except subprocess.TimeoutExpired:
        return 'TIME', data
    finally:
        try: os.unlink(p)
        except: pass

def main():
    start=time.time(); rng=random.Random(123); crash=[]
    total=30000
    with ThreadPoolExecutor(max_workers=16) as ex:
        futs=[ex.submit(run_one,build_png(rng)) for _ in range(total)]
        for f in as_completed(futs):
            rc,data=f.result()
            if rc not in (0,1):
                print('CRASH',rc,'time',time.time()-start,file=sys.stderr); crash.append((rc,data)); break
    print('done',len(crash),'time',time.time()-start)
    if crash: open('/tmp/crash_png.bin','wb').write(crash[0][1])
main()
