# top-level ftyp + arbitrary boxes
BOX_TYPES=[b'ftyp',b'meta',b'mdat',b'moov',b'trak',b'udta',b'free',b'skip',b'uuid',b'iprp',b'ipco',b'iinf',b'iloc',b'pitm',b'infe',b'Exif',b'iref',b'idat']
def box(typ,payload, size=None):
    sz=size if size is not None else 8+len(payload)
    return struct.pack('>I',sz)+typ+payload

